#include "test.hpp"
#include "mspa/c_api.h"
int main(){mspa_runtime_config c{};c.runtime_id=1;c.world_id=10;c.time_domain_id=1;c.ticks_per_second_num=1;c.ticks_per_second_den=1;c.seed_root=5;c.diagnostics_enabled=1;mspa_runtime*r=nullptr;require(mspa_runtime_create(&c,&r)==MSPA_OK&&r,"c runtime");mspa_agent_id a{10,1};require(mspa_agent_create(r,a,1)==MSPA_OK,"c agent create");require(mspa_agent_has(r,a),"c has");mspa_expected_effect eff{};eff.channel=0;eff.concept_id=99;eff.magnitude=1.0f;mspa_action_option opt{};opt.type_id=1;opt.instance_id=1;opt.continuity_key=1;opt.progress=0.1f;opt.context_stability=1.0f;opt.expected_effects=&eff;opt.expected_effect_count=1;mspa_need_signal need{99,1.0f};mspa_decision_result d{};require(mspa_decide_ex(r,a,&opt,1,&need,1,nullptr,0,0.0f,2,0,&d)==MSPA_OK&&d.has_selection,"c decide ex");require(mspa_report(r,a,1,1,3)==MSPA_OK,"c report");mspa_buffer b{};require(mspa_agent_export(r,a,4,&b)==MSPA_OK&&b.data&&b.size,"c export");mspa_buffer_free(&b);require(mspa_agent_remove(r,a,5)==MSPA_OK,"c remove");mspa_runtime_destroy(r);require(mspa_version_major()>=1,"c version");std::cout<<"c api ok\n";}
